using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Runtime.Serialization.Json;using GlassBoard;
public static class Feedback18Tests {
    static int checks;static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
    static T Read<T>(string json){using(var stream=new MemoryStream(Encoding.UTF8.GetBytes(json)))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(stream);}
    static T Round<T>(T value){using(var stream=new MemoryStream()){var serializer=new DataContractJsonSerializer(typeof(T));serializer.WriteObject(stream,value);stream.Position=0;return (T)serializer.ReadObject(stream);}}
    static int Main(){
        foreach(bool old in new[]{false,true}){var options=Read<DockOptions>("{\"MotionEnabled\":"+old.ToString().ToLowerInvariant()+"}");options.Normalize();Check(options.OpenMotion==old&&options.HoverMotion==old,"upgrade preserves legacy toggle");options.OpeningAnimation=false;options.HoverAnimation=true;var saved=Round(options);Check(!saved.OpenMotion&&saved.HoverMotion,"hover is independent from disabled opening");saved.OpeningAnimation=true;saved.HoverAnimation=false;Check(saved.OpenMotion&&!saved.HoverMotion,"opening independent from disabled hover");}
        foreach(string style in InteractionRules.OpenStyles)foreach(string hover in InteractionRules.HoverStyles){var options=new DockOptions{OpenAnimationStyle=style,HoverAnimationStyle=hover};var saved=Round(options);saved.Normalize();Check(saved.OpenAnimationStyle==style&&saved.HoverAnimationStyle==hover,"all animation selections persist");}
        var bad=new DockOptions{OpenAnimationStyle="oops",HoverAnimationStyle=null};bad.Normalize();Check(bad.OpenAnimationStyle=="fade"&&bad.HoverAnimationStyle=="zoom-lift","invalid style normalization");
        foreach(bool hide in new[]{false,true})foreach(bool top in new[]{false,true}){var options=new DockOptions{AutoHide=hide,AlwaysOnTop=top};Check(InteractionRules.DockTopmost(options,false)==top,"auto-hide never changes topmost");Check(InteractionRules.DockTopmost(options,true),"explicit drag can temporarily show dock");}
        var p=Read<Preferences>("{\"AutoCheckUpdates\":true,\"UpdateDirectConnection\":true,\"LastUpdateCheckUtc\":1234,\"Apps\":[{\"Path\":\"keep.exe\",\"Name\":\"保留\"}]}");p.Normalize();Check(!p.AutoCheckUpdates&&!p.UpdateDirectConnection&&p.LastUpdateCheckUtc==0,"retired updater switches ignored after migration");Check(p.Apps.Count==1,"updater migration retains data");
        var legacy20=Read<Preferences>("{}");legacy20.Normalize();Check(legacy20.BoardPageMotion&&legacy20.BoardPageStyle=="slide"&&!legacy20.AllDesktopLayer,"legacy page/layer defaults");
        foreach(string pageStyle in new[]{"fade","slide","scale"}){var pagePrefs=Round(new Preferences{AllDesktopLayer=true,BoardPageMotion=false,BoardPageStyle=pageStyle});pagePrefs.Normalize();Check(pagePrefs.AllDesktopLayer&&!pagePrefs.BoardPageMotion&&pagePrefs.BoardPageStyle==pageStyle,"page and layer options persist independently");}
        var oldOrb=Read<ControlCenterOptions>("{}");oldOrb.Normalize();Check(oldOrb.ShowControl&&oldOrb.ShowTray&&oldOrb.ShowStart,"legacy orb entries enabled");
        for(int mask=0;mask<8;mask++){var orb=Round(new ControlCenterOptions{ShowControl=(mask&1)!=0,ShowTray=(mask&2)!=0,ShowStart=(mask&4)!=0});Check(orb.ShowControl==((mask&1)!=0)&&orb.ShowTray==((mask&2)!=0)&&orb.ShowStart==((mask&4)!=0),"all independent entry combinations persist");}
        var fresh=new WidgetOptions();fresh.Normalize();foreach(string kind in WidgetRules.Kinds)Check(!fresh.Style(kind).Frameless,"first-use widget is framed");fresh.Style("clock").Frameless=true;fresh=Round(fresh);fresh.Normalize();Check(fresh.Style("clock").Frameless,"saved frameless choice preserved");
        var snapshot=new SystemSnapshot{Radios=new List<RadioSnapshot>(),Errors=new List<string>{"无线：API load failed"}};Check(InteractionRules.WirelessState(snapshot,"WiFi").Contains("受限"),"read failure is not mislabeled missing adapter");snapshot.Errors.Clear();Check(InteractionRules.WirelessState(snapshot,"WiFi")=="未检测到适配器","successful absence distinguished");snapshot.Radios.Add(new RadioSnapshot{Kind="Bluetooth",Available=false});Check(InteractionRules.WirelessState(snapshot,"Bluetooth").Contains("已检测到"),"native presence not mislabeled absent");snapshot.Radios.Add(new RadioSnapshot{Kind="WiFi",Available=true,Enabled=true});Check(InteractionRules.WirelessState(snapshot,"WiFi")=="已开启","native wifi fallback can show live state");
        var prefs=new Preferences();var without=prefs.Dock.WidthFor(4);prefs.Dock.ShowRecycleBin=true;Check(prefs.Dock.WidthFor(4)>without,"recycle bin reserves width");Check(DockLayoutRules.Common(prefs,true).Contains(DockLayoutRules.RecycleBin),"recycle bin visible when enabled");prefs.Dock.ShowRecycleBin=false;Check(!DockLayoutRules.Common(prefs,true).Contains(DockLayoutRules.RecycleBin),"recycle bin optional");
        string folder=Path.Combine(Path.GetTempPath(),"gb18-components-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{var files=ComponentFiles.Inspect(folder);Check(files.Count==1&&files[0].Name=="lib/NPSMLib.dll"&&files.All(f=>!f.Valid&&!f.Blocked),"compatibility scan targets exact shipped DLLs only");Directory.CreateDirectory(Path.Combine(folder,"lib"));File.WriteAllText(Path.Combine(folder,"lib/NPSMLib.dll"),"changed");files=ComponentFiles.Inspect(folder);Check(files.All(f=>!f.Valid),"foreign DLL cannot be approved for unblock");}finally{Directory.Delete(folder,true);}
        string report=AiSupport.Build("天气","sample error");Check(report.Contains("sample error")&&report.Contains("最小补丁")&&report.Contains("复现步骤")&&report.Contains(".NET Framework 4.8"),"editable AI handoff contains actual error, environment and patch instructions");Check(AiSupport.Build("WiFi",null).Contains("暂未记录具体错误"),"no error is not invented");
        Console.WriteLine(checks+" feedback18 migration, animation, layer, wireless and package-option checks PASS");return 0;
    }
}
